INSERT INTO crop_observation.crop_stage_translations VALUES ('134d4cd8-0894-4d9a-8cf7-50acda3a179b', '04a9eb28-3f2a-4932-bb77-1b5b9230bdb3', 'en-IN', 'Seedling', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('57fc16a5-b08c-492a-a8c7-9bf9d65a43fb', '2f895439-2d3e-4174-bc89-5f021d7303bf', 'or-IN', 'ବଢ଼ିବା ଅବସ୍ଥା', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('b81f99c1-88d0-45fd-973b-51f073b9d27c', '2f895439-2d3e-4174-bc89-5f021d7303bf', 'en-IN', 'Vegetative Growth', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('bfd9d46c-c2d6-4efd-b890-058fda4e3aef', '5a55ac01-3e8e-4c29-b049-7db67bf69cc8', 'or-IN', 'ମଞ୍ଜରୀ ଆରମ୍ଭ', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('03120721-626b-453e-83ee-ea34343995ef', '5a55ac01-3e8e-4c29-b049-7db67bf69cc8', 'en-IN', 'Panicle Initiation', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('dbb03591-3cad-44df-b2ae-31479e30520f', '37738b9f-4acd-49e1-9c65-f3e461480d0e', 'or-IN', 'ଫୁଲ ଅବସ୍ଥା', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('c9462c9f-4671-47dd-9fb7-9959e2ca5fc4', '37738b9f-4acd-49e1-9c65-f3e461480d0e', 'en-IN', 'Flowering', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('7146c307-b05e-4572-989b-8b404e4368d5', '9c79eec4-bd8d-4b2b-91dd-9137207d4937', 'or-IN', 'ଦାନା ପୂରଣ', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('4714f453-3731-436c-bfe8-e95207e89e8b', '9c79eec4-bd8d-4b2b-91dd-9137207d4937', 'en-IN', 'Grain Filling', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('a0cd1802-6db0-423d-b540-a87c7bfeba64', '3a4112b7-7bb2-440d-92ea-fac5467775bf', 'or-IN', 'ପାଚିବା ଅବସ୍ଥା', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('38634c3b-4bb4-458f-b950-002de29971d2', '3a4112b7-7bb2-440d-92ea-fac5467775bf', 'en-IN', 'Ripening', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('639eea83-0fc4-41f9-a75c-5ee13c7ffa81', '55dfda1e-d1c3-4dd3-b329-e9dbf973e771', 'or-IN', 'ଅମଳ', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('11aefdd6-8f1e-449d-9155-738716152af6', '55dfda1e-d1c3-4dd3-b329-e9dbf973e771', 'en-IN', 'Harvesting', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('24923d62-ee63-4642-baa7-b51fff293595', 'fd2842a0-0764-4b15-b8da-3491ec2e61bd', 'or-IN', 'ଅମଳ ପରେ', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('a733abf4-0cb5-4ffa-b59c-9d455a9d6dc1', 'fd2842a0-0764-4b15-b8da-3491ec2e61bd', 'en-IN', 'Post Harvest', NULL, NULL);
INSERT INTO crop_observation.crop_stage_translations VALUES ('48d5b30c-13f9-4a5d-acaa-f32a0f509e0a', '6a276930-d856-4a85-92a8-880e55b91a48', 'or-IN', 'ଅମଳ ପରେ', 'ଛାଟାଇ, ସଞ୍ଚୟ ଓ ବଜାର ପାଇଁ ପ୍ରସ୍ତୁତି।', 'ଗ୍ରେଡିଙ୍ଗ, ସଞ୍ଚୟ ଓ ପରଅମଳ ପରିଚାଳନା ଲେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('c34cf0d5-9ccf-4c44-9f75-17f17b2447f2', '6a276930-d856-4a85-92a8-880e55b91a48', 'en-IN', 'Post Harvest', 'Sorting, storage, and market preparation.', 'Track grading, storage, and post-harvest handling.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('4601a7aa-8dae-4eb3-9123-7ce138d3572b', '7ddf0b99-59bc-4317-a7cb-0292c50637dc', 'or-IN', 'ଅମଳ', 'ପକ୍କା ଫଳ ସଂଗ୍ରହ କରାଯାଉଛି।', 'ଅମଳ ସମୟ, ପ୍ରକ୍ରିୟା ଓ ଉତ୍ପାଦନ ଲେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('5d24b425-09e9-4cac-8453-4110e86334e7', '7ddf0b99-59bc-4317-a7cb-0292c50637dc', 'en-IN', 'Harvesting', 'Mature fruits are being picked.', 'Record harvest timing, method, and yield.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('087a7993-08d3-4280-b9ea-c03f10952bc4', 'bfed184d-cb71-4390-92fb-900e6b2bc9ee', 'or-IN', 'ଫଳ ବିକାଶ', 'ଫଳ ଭରୁଛି ଓ ପକ୍କା ହେଉଛି।', 'ଆକାର, ରଙ୍ଗ, ପୋକ ଓ ପାଣି ଆବଶ୍ୟକତା ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('42f62de7-cd56-4416-b84d-6180e62bcd5e', 'bfed184d-cb71-4390-92fb-900e6b2bc9ee', 'en-IN', 'Fruit Development', 'Fruits are filling and maturing.', 'Watch size, colour, pests, and orchard water needs.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('3ed31963-33b6-4e87-860f-ad6b3f9ac51a', '31599dfd-d828-4824-b3ac-466edf233c59', 'or-IN', 'ଫଳ ଧରା', 'ଛୋଟ ଫଳ ଧରୁଛି ଓ ଟିକି ରହୁଛି।', 'ଫଳ ଝରା, ପୋଷକ ଓ ରୋଗ ସଙ୍କେତ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('2709238d-c97a-41c9-885e-054e7155d147', '31599dfd-d828-4824-b3ac-466edf233c59', 'en-IN', 'Fruit Set', 'Small fruits are setting and retaining.', 'Track fruit drop, nutrition, and disease signs.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('4c0d16c9-3ccc-442a-bbee-9afc8106e9dd', '82c1210d-5bfb-4b90-b496-c3e4ce3a3720', 'or-IN', 'ଫୁଲ ଅବସ୍ଥା', 'ମଞ୍ଜରୀ ଓ ଫୁଲ ଦେଖାଯାଉଛି।', 'ଫୁଲର ସ୍ୱାସ୍ଥ୍ୟ, ପୋକ ଚାପ ଓ ଛିଟାଇ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('11c3c16a-e849-4399-8151-1fe35f06025f', '82c1210d-5bfb-4b90-b496-c3e4ce3a3720', 'en-IN', 'Flowering', 'Panicles and blooms are active.', 'Observe bloom health, pest pressure, and sprays.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('beb4447b-4c29-4379-8d6a-d17a08942a24', 'fdabd8e9-d8df-4d90-b1f1-f037a2ce8294', 'or-IN', 'ପତ୍ର ବୃଦ୍ଧି', 'ନୂତନ ପତ୍ର ଓ ଶାଖା ବୃଦ୍ଧି ହେଉଛି।', 'ବଗିଚା ସ୍ୱାସ୍ଥ୍ୟ, ପୋଷକ ଓ ଆରମ୍ଭିକ ରୋଗ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('39e312c4-028c-467e-bcaa-f6065a431f0f', 'fdabd8e9-d8df-4d90-b1f1-f037a2ce8294', 'en-IN', 'Vegetative Flush', 'New shoots and canopy are flushing.', 'Track orchard health, nutrition, and disease early.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('aa468371-86f0-45ab-8c74-dc071a1c4ffa', '6220f6f6-15d2-480e-bbf5-4f3a21f29e62', 'or-IN', 'ଅମଳ', 'ପକ୍କା ଗୁଛା ସଂଗ୍ରହ କରାଯାଉଛି।', 'ଅମଳ ପ୍ରକ୍ରିୟା, ପରିମାଣ ଓ କ୍ଷତି ଲେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('2bae0075-e3e1-4620-8bc8-5dc13bbabccc', '6220f6f6-15d2-480e-bbf5-4f3a21f29e62', 'en-IN', 'Harvesting', 'Harvest-ready bunches are being collected.', 'Record harvest method, quantity, and visible losses.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('d199da97-04aa-454e-b632-f0d8d94c0d6d', 'e06c549c-33f8-47a5-a56e-c2de9b74a3ae', 'or-IN', 'ନଡ଼ିଆ ବିକାଶ', 'ନଡ଼ିଆ ଫଳ ଗଠନ ଓ ବିକାଶ ହେଉଛି।', 'ଫଳ ଧରା, ଜଳ ଅଭାବ ଓ କ୍ଷତି ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('ba365277-5fe2-4381-8da3-f9b07d2bf882', 'e06c549c-33f8-47a5-a56e-c2de9b74a3ae', 'en-IN', 'Nut Development', 'Tender and mature nuts are developing.', 'Track nut set, water stress, and damage.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('3c0ae409-c4aa-4361-b80f-6c94e0b4c151', '09722d6e-1b7b-468b-bfd9-7e6d91ffeb3a', 'or-IN', 'ଫୁଲ ଅବସ୍ଥା', 'ଗଛରେ ଫୁଲ ଓ ଫଳାଣ ପ୍ରକ୍ରିୟା ଚାଲିଛି।', 'ଫୁଲର ଅବସ୍ଥା, ପୋକ ଓ ପୋଷକ ନିୟମିତ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('52db3099-fe5c-430e-8589-c0f8ed12fbf0', '09722d6e-1b7b-468b-bfd9-7e6d91ffeb3a', 'en-IN', 'Flowering', 'Inflorescence and female flowers are active.', 'Note flowering intensity, pests, and timely nutrition.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('b774bdb4-0021-4494-ada3-a474fdbbd567', 'ae9f318c-c892-4317-9cbd-a5d97f00830c', 'or-IN', 'ବୃଦ୍ଧି ଅବସ୍ଥା', 'ଗଛ ପତ୍ର ଓ ତଣ୍ଟ ବୃଦ୍ଧି କରୁଛି।', 'ପତ୍ରର ରଙ୍ଗ, ପାଣି ଓ ବଗିଚା ପରିଚାଳନା ଧ୍ୟାନରେ ରଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('111572b8-fdc7-43b2-b46b-87023c9e6074', 'ae9f318c-c892-4317-9cbd-a5d97f00830c', 'en-IN', 'Vegetative', 'Palm is expanding leaves and stem.', 'Watch leaf colour, irrigation, and orchard upkeep.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('04910272-454b-4da5-b360-e561e1d76236', '5746c051-49ed-43d1-8e42-78b573a87151', 'or-IN', 'ସ୍ଥାପନ', 'ନୂଆ ଗଛ ମୂଳ ଓ ପତ୍ର ଗଠନ କରୁଛି।', 'ରୋପଣ ପରବର୍ତ୍ତୀ ସ୍ୱାସ୍ଥ୍ୟ, ପାଣି ଓ ପ୍ରଥମ ପୋଷକ ଧ୍ୟାନରେ ରଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('7c3ec48b-ee9f-4b2e-b3be-c176646a7454', '5746c051-49ed-43d1-8e42-78b573a87151', 'en-IN', 'Establishment', 'Young palms establish roots and canopy.', 'Track planting health, irrigation, and first nutrient support.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('827e0592-72de-4312-a7c4-ead856d4e75e', '49a6079f-3769-43c7-9075-9f944b331ce0', 'or-IN', 'ଅମଳ ପରେ', 'ଛାଟାଇ, ସଞ୍ଚୟ ଓ ବଜାର ପାଇଁ ପ୍ରସ୍ତୁତି।', 'ଗ୍ରେଡିଙ୍ଗ, ସଞ୍ଚୟ ଓ ପରଅମଳ ପରିଚାଳନା ଲେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('de9556d4-0cdd-453a-9a9c-6d28405d5d80', '49a6079f-3769-43c7-9075-9f944b331ce0', 'en-IN', 'Post Harvest', 'Sorting, storage, and market preparation.', 'Track grading, storage, and post-harvest handling.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('6b4910cb-d47f-474d-87c3-d7cee6b25362', '5c36fec6-8dd3-4bb7-a57a-1cd2f2928f2b', 'en-IN', 'Fruit Development', 'Fruits are filling and maturing.', 'This is the fruit growth stage. Check if the fruits are growing well, if there are spots on fruits, or if fruits are cracking.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('17fb9bd8-0aff-4528-9606-dc7d3a5f7d95', '64fed313-ecb2-4394-8616-361a858f99d2', 'en-IN', 'Harvesting', 'Mature fruits are being picked.', 'This is the maturity stage. Check if the fruit color is changing, if fruits are falling, and if it is the right time for harvest.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('a2a16089-4129-4103-8e37-0e0b204b626f', '64fed313-ecb2-4394-8616-361a858f99d2', 'or-IN', 'ଅମଳ', 'ପକ୍କା ଫଳ ସଂଗ୍ରହ କରାଯାଉଛି।', 'ଏହା ଆମ୍ବ ପାକିବା ଅବସ୍ଥା। ଫଳର ରଙ୍ଗ ବଦଳୁଛି କି, ଫଳ ପଡୁଛି କି, ଏବଂ କଟାଇ ପାଇଁ ଠିକ୍ ସମୟ ହୋଇଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('a083879f-c6e5-41c8-9d43-c51e9e6c5399', '5c36fec6-8dd3-4bb7-a57a-1cd2f2928f2b', 'or-IN', 'ଫଳ ବିକାଶ', 'ଫଳ ଭରୁଛି ଓ ପକ୍କା ହେଉଛି।', 'ଏହା ଆମ୍ବ ବଢିବା ଅବସ୍ଥା। ଫଳର ଆକାର ଭଲ ବଢୁଛି କି, ଫଳରେ ଦାଗ ଅଛି କି, ବା ଫଳ ଫାଟୁଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('5871df77-8491-4724-a8b3-ad93b024e73c', '9014807d-b0d3-44c5-872e-80606b67c652', 'or-IN', 'ଅମଳ ପରେ', 'ଛାଟାଇ, ସଞ୍ଚୟ ଓ ବଜାର ପାଇଁ ପ୍ରସ୍ତୁତି।', 'ଗ୍ରେଡିଙ୍ଗ, ସଞ୍ଚୟ ଓ ପରଅମଳ ପରିଚାଳନା ଲେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('8616fccc-5f5b-4091-9eeb-4556b3e1fefc', '9014807d-b0d3-44c5-872e-80606b67c652', 'en-IN', 'Post Harvest', 'Sorting, storage, and market preparation.', 'Track grading, storage, and post-harvest handling.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('b605e899-4cb5-4612-b393-2cef7d415a6b', '929e7612-42b3-4c2c-bce8-4559005baa1d', 'en-IN', 'Harvesting', 'Mature fruits are being picked.', 'This is the maturity stage. Check if the fruit color is changing, if fruits are falling, and if it is the right time for harvest.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('d8a8783b-0675-42a5-8e30-037361bb9af9', '929e7612-42b3-4c2c-bce8-4559005baa1d', 'or-IN', 'ଅମଳ', 'ପକ୍କା ଫଳ ସଂଗ୍ରହ କରାଯାଉଛି।', 'ଏହା ଆମ୍ବ ପାକିବା ଅବସ୍ଥା। ଫଳର ରଙ୍ଗ ବଦଳୁଛି କି, ଫଳ ପଡୁଛି କି, ଏବଂ କଟାଇ ପାଇଁ ଠିକ୍ ସମୟ ହୋଇଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('6ef8e09e-b073-4d20-ae65-a8b365d6169f', '59d75bb1-f149-43a8-aaed-b7b3babb75ae', 'or-IN', 'ପତ୍ର ବୃଦ୍ଧି', NULL, 'ନମସ୍କାର। ଏହା ଆମ୍ବ ଗଛର ନୂଆ ପତ୍ର ଆସିବା ଅବସ୍ଥା। ଆପଣ ଯାହା ଗଛରେ ଦେଖୁଛନ୍ତି, ସେହି ଅନୁସାରେ ଫର୍ମ ଭରନ୍ତୁ। ଗଛର ଫଟୋ ଅପଲୋଡ୍ କରନ୍ତୁ। ଆପଣ ଚାହିଲେ ମାଇକ୍ ବଟନ୍ ଦବାଇ ନିଜ ସମସ୍ୟା କହିପାରିବେ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('d1b2a1d8-9ff7-4a31-b227-2d6b53b4b629', '59d75bb1-f149-43a8-aaed-b7b3babb75ae', 'en-IN', 'Vegetative Flush', NULL, 'Namaskar. This is the new leaf stage of mango. Please fill the form based on what you see in the tree. Upload a photo of the tree. You can also tap the mic button and record your issue in your own words.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('8789f258-3840-457e-a7ae-a414bc876d56', '936f123a-de53-43e7-9380-0cf712bed4d6', 'en-IN', 'Fruit Development', 'Fruits are filling and maturing.', 'This is the fruit growth stage. Check if the fruits are growing well, if there are spots on fruits, or if fruits are cracking.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('2a4716bd-a6f1-4d50-9444-a3598294d4a0', '936f123a-de53-43e7-9380-0cf712bed4d6', 'or-IN', 'ଫଳ ବିକାଶ', 'ଫଳ ଭରୁଛି ଓ ପକ୍କା ହେଉଛି।', 'ଏହା ଆମ୍ବ ବଢିବା ଅବସ୍ଥା। ଫଳର ଆକାର ଭଲ ବଢୁଛି କି, ଫଳରେ ଦାଗ ଅଛି କି, ବା ଫଳ ଫାଟୁଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('60768e64-ddc8-4c4b-b601-e5b2b90a805a', '8d022829-f85a-4fe1-b13f-31d6ecf0f9a5', 'or-IN', 'ଫଳ ଧରା', 'ଛୋଟ ଫଳ ଧରୁଛି ଓ ଟିକି ରହୁଛି।', 'ଏହା ଛୋଟ ଆମ୍ବ ଧରିବା ଅବସ୍ଥା। ଛୋଟ ଫଳ ଝରିଯାଉଛି କି, ଫଳ କମ୍ ଧରିଛି କି, ବା ପତ୍ର ଏବଂ ଫୁଲରେ ପୋକ ଅଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('efabc558-696e-4777-8fb5-953707929408', '8d022829-f85a-4fe1-b13f-31d6ecf0f9a5', 'en-IN', 'Fruit Set', 'Small fruits are setting and retaining.', 'This is the fruit setting stage. Check if small fruits are falling, if fruit setting is low, or if pests are visible on leaves and flowers.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('d770d3e2-2fcd-4ad7-afe7-37b99681927a', 'be81919c-5c19-4e5f-b691-d551125c8bbb', 'or-IN', 'ଫୁଲ ଅବସ୍ଥା', 'ମଞ୍ଜରୀ ଓ ଫୁଲ ଦେଖାଯାଉଛି।', 'ଏହା ଆମ୍ବ ଫୁଲ ଆସିବା ଅବସ୍ଥା। ଫୁଲ ଭଲ ଆସୁଛି କି, ଫୁଲ ଝରୁଛି କି, ବା ପୋକ ଓ ଧଳା ପାଉଡର ଭଳି ରୋଗ ଦେଖାଯାଉଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('fc836db1-80d7-4598-8b73-a26d65c15454', 'be81919c-5c19-4e5f-b691-d551125c8bbb', 'en-IN', 'Flowering', 'Panicles and blooms are active.', 'This is the flowering stage of mango. Check if flowering is good, if flowers are falling, or if pests or white powder-like disease are visible.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('d7c12442-7e29-46bc-b85f-9c0107c65918', 'ae8797bb-9c5b-4d21-8a3e-27bf17be178c', 'or-IN', 'ଫଳ ଧରା', 'ଛୋଟ ଫଳ ଧରୁଛି ଓ ଟିକି ରହୁଛି।', 'ଏହା ଛୋଟ ଆମ୍ବ ଧରିବା ଅବସ୍ଥା। ଛୋଟ ଫଳ ଝରିଯାଉଛି କି, ଫଳ କମ୍ ଧରିଛି କି, ବା ପତ୍ର ଏବଂ ଫୁଲରେ ପୋକ ଅଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('f5753320-e0e0-49ae-9ec8-7f0db9efd593', 'ae8797bb-9c5b-4d21-8a3e-27bf17be178c', 'en-IN', 'Fruit Set', 'Small fruits are setting and retaining.', 'This is the fruit setting stage. Check if small fruits are falling, if fruit setting is low, or if pests are visible on leaves and flowers.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('a7c9518c-8d30-4921-83cc-b97382cfbdb7', '84b98a59-8a7c-46b8-ab05-0afe2bd9d916', 'or-IN', 'ଫୁଲ ଅବସ୍ଥା', 'ମଞ୍ଜରୀ ଓ ଫୁଲ ଦେଖାଯାଉଛି।', 'ଏହା ଆମ୍ବ ଫୁଲ ଆସିବା ଅବସ୍ଥା। ଫୁଲ ଭଲ ଆସୁଛି କି, ଫୁଲ ଝରୁଛି କି, ବା ପୋକ ଓ ଧଳା ପାଉଡର ଭଳି ରୋଗ ଦେଖାଯାଉଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('4b698bfa-1998-4b57-a21b-3941eb0ea9c1', '84b98a59-8a7c-46b8-ab05-0afe2bd9d916', 'en-IN', 'Flowering', 'Panicles and blooms are active.', 'This is the flowering stage of mango. Check if flowering is good, if flowers are falling, or if pests or white powder-like disease are visible.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('b689afd7-53ca-4f77-acc8-701e4c57523f', 'e1d6c2d0-c4cf-4701-b057-bfef8624eeb3', 'or-IN', 'ପତ୍ର ବୃଦ୍ଧି', NULL, 'ନମସ୍କାର। ଏହା ଆମ୍ବ ଗଛର ନୂଆ ପତ୍ର ଆସିବା ଅବସ୍ଥା। ଆପଣ ଯାହା ଗଛରେ ଦେଖୁଛନ୍ତି, ସେହି ଅନୁସାରେ ଫର୍ମ ଭରନ୍ତୁ। ଗଛର ଫଟୋ ଅପଲୋଡ୍ କରନ୍ତୁ। ଆପଣ ଚାହିଲେ ମାଇକ୍ ବଟନ୍ ଦବାଇ ନିଜ ସମସ୍ୟା କହିପାରିବେ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('755c422d-5ba2-4677-877d-b2942f243586', 'e1d6c2d0-c4cf-4701-b057-bfef8624eeb3', 'en-IN', 'Vegetative Flush', NULL, 'Namaskar. This is the new leaf stage of mango. Please fill the form based on what you see in the tree. Upload a photo of the tree. You can also tap the mic button and record your issue in your own words.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('b2ba6ce1-02a2-43fb-a380-b0e7f6d226d3', '213c36e7-afa6-412f-adf6-3085136af8e3', 'en-IN', 'Panicle Initiation', NULL, 'This is the stage when panicle development begins. At this time the crop needs water and nutrients. Check whether the leaves are curling, turning yellow, or whether the plants look weak.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('0e646af6-e5d1-4e23-a2ff-bb532ff49963', '8bd9bd0b-30c1-4bd7-835d-d9412b1894ec', 'en-IN', 'Flowering', NULL, 'This is the flowering stage. Check whether flowering is proper, whether the panicles look empty, or whether pests are visible.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('dace942e-5f38-480b-bd1e-bce700f6275b', '188fedff-f8c8-4803-8f13-2241f5a66f6b', 'or-IN', 'ଅମଳ ପରେ', 'ଛାଟାଇ, ସଞ୍ଚୟ ଓ ବଜାର ପାଇଁ ପ୍ରସ୍ତୁତି।', 'ଗ୍ରେଡିଙ୍ଗ, ସଞ୍ଚୟ ଓ ପରଅମଳ ପରିଚାଳନା ଲେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('09d72f86-fd7e-4a2b-931c-dc3f0b04907a', '188fedff-f8c8-4803-8f13-2241f5a66f6b', 'en-IN', 'Post Harvest', 'Sorting, storage, and market preparation.', 'Track grading, storage, and post-harvest handling.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('e86e40fd-00d9-446c-aee8-1cd4e40c7e16', '6ba2c45f-c940-4b6c-a9e4-6e4fcc4d23fd', 'en-IN', 'Harvesting', 'Mature fruits are being picked.', 'This is the maturity stage. Check if the fruit color is changing, if fruits are falling, and if it is the right time for harvest.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('3a62252c-18ee-4c56-86c1-905cf266dd7b', '8bd9bd0b-30c1-4bd7-835d-d9412b1894ec', 'or-IN', 'ଫୁଲ ଅବସ୍ଥା', NULL, 'ଏହା ଫୁଲ ଆସିବା ଅବସ୍ଥା। ଏହି ସମୟରେ ଖେତରେ ପାଣି କମ୍ ହେବା ଉଚିତ୍ ନୁହେଁ। ଫୁଲ ଠିକ୍ ଆସୁଛି କି, କେଣ୍ଡା ଖାଲି ଦେଖାଯାଉଛି କି, ବା ପୋକ ଲାଗିଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('dab6ccdd-30fe-4efb-9e3e-0fa9db80434e', '22bdaef8-fa86-4db7-b8a2-7017ced20b80', 'en-IN', 'Grain Filling', NULL, 'This is the grain filling stage. Check whether the panicles are filling properly, whether the grains feel light, and whether the plants are starting to dry early. If you want, record the condition in your own words.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('522e2b24-4836-49a9-9fd2-a5cc98dda267', '22bdaef8-fa86-4db7-b8a2-7017ced20b80', 'or-IN', 'ଦାନା ପୂରଣ', NULL, 'ଏହା ଧାନ ଦାନା ଭରିବା ଅବସ୍ଥା। କେଣ୍ଡା ଭଲ ଭାବରେ ଭରୁଛି କି, ଦାନା ହାଲୁକା ଅଛି କି, ଏବଂ ଗଛ ଶୁଖିବା ଆରମ୍ଭ କରିଛି କି ନାହିଁ ଦେଖନ୍ତୁ। ଚାହିଁଲେ ନିଜ ଅବସ୍ଥା କହି ରେକର୍ଡ କରନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('60b4d289-a002-436e-ba54-d2aed45e011f', '6ba2c45f-c940-4b6c-a9e4-6e4fcc4d23fd', 'or-IN', 'ଅମଳ', 'ପକ୍କା ଫଳ ସଂଗ୍ରହ କରାଯାଉଛି।', 'ଏହା ଆମ୍ବ ପାକିବା ଅବସ୍ଥା। ଫଳର ରଙ୍ଗ ବଦଳୁଛି କି, ଫଳ ପଡୁଛି କି, ଏବଂ କଟାଇ ପାଇଁ ଠିକ୍ ସମୟ ହୋଇଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('37ca8bde-14da-4f26-affd-c424b5f5f0ec', 'f33e6456-fb48-43d3-9bd1-0c80be2847f2', 'en-IN', 'Fruit Development', 'Fruits are filling and maturing.', 'This is the fruit growth stage. Check if the fruits are growing well, if there are spots on fruits, or if fruits are cracking.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('ce711e28-bab5-4712-9cf6-e484f24a4a6f', '5398ad64-ccc7-4d8a-a5f7-df8cb26803a9', 'or-IN', 'ଅମଳ', NULL, 'ଏହା ଧାନ କଟା ହେବାର ପୂର୍ବ ଅବସ୍ଥା। ଧାନ ଦାନା ପାଚିଛି କି, ଗଛ ଅଧିକ ଶୁଖୁଛି କି, ଏବଂ କଟା ହେବା ପାଇଁ ଠିକ୍ ସମୟ ହୋଇଛି କି ନାହିଁ ଦେଖନ୍ତୁ। ଫଟୋ ଦେଲେ ଆମେ ଭଲ ଭାବରେ ବୁଝିପାରିବୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('5d8c9e8f-8229-4fb8-91f5-3b1ddebff009', '5398ad64-ccc7-4d8a-a5f7-df8cb26803a9', 'en-IN', 'Harvesting', NULL, 'This is the stage before harvesting. Check whether the grains have matured, whether the plants are becoming too dry, and whether it is the right time for harvesting. A photo will help us understand the condition better.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('b31e3eab-1e53-4203-a8e6-a01815f5a8a2', '213c36e7-afa6-412f-adf6-3085136af8e3', 'or-IN', 'ମଞ୍ଜରୀ ଆରମ୍ଭ', NULL, 'ଏହା ଧାନ କେଣ୍ଡା ବାହାରିବା ଆରମ୍ଭ ଅବସ୍ଥା। ଏହି ସମୟରେ ଗଛକୁ ପାଣି ଏବଂ ପୋଷକ ଦରକାର। ପତ୍ର ମୋଡ଼ି ହେଉଛି କି, ହଳଦିଆ ଦେଖାଯାଉଛି କି, ବା ଗଛ ଦୁର୍ବଳ ଦେଖାଯାଉଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('5c41361a-ff69-4bfb-8048-8234cd3962b1', 'bd898a8c-fdb6-4d69-b2c2-4dc84a5df6fb', 'en-IN', 'Transplanting Stage', NULL, 'This is the transplanting stage of Kala Jeera paddy. Check whether the seedlings are established properly, whether there is enough water, and whether any plants look yellow. If you want, you can record your problem in your own words.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('7ec7559c-a9f4-40bd-9f5e-cd83d51b2a2d', 'bd898a8c-fdb6-4d69-b2c2-4dc84a5df6fb', 'or-IN', 'ଜିରା ଧାନର ରୋପଣ', NULL, 'ଏହା କଳା ଜିରା ଧାନର ରୋପଣ ଅବସ୍ଥା। ଚାରା ଠିକ୍ ଭାବରେ ଲାଗିଛି କି ନାହିଁ, ପାଣି ଅଛି କି ନାହିଁ, ଏବଂ ଗଛ ହଳଦିଆ ଦେଖାଯାଉଛି କି ନାହିଁ, ଧ୍ୟାନରେ ଦେଖନ୍ତୁ। ଆପଣ ଚାହିଁଲେ ନିଜ ସମସ୍ୟା କଥାରେ ରେକର୍ଡ କରିପାରିବେ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('89609451-63c7-4476-9ea5-f874898f64a3', 'c535e8b7-1f6d-4014-a60f-b44934ef8c78', 'en-IN', 'Seedling', NULL, 'Namaskar.
INSERT INTO crop_observation.crop_stage_translations VALUES ('5553bf54-3ba5-405f-9132-f2c54c387de3', 'c535e8b7-1f6d-4014-a60f-b44934ef8c78', 'or-IN', 'ଚାରା ଅବସ୍ଥା', NULL, 'ନମସ୍କାର।
INSERT INTO crop_observation.crop_stage_translations VALUES ('ec7173bf-1f90-4da8-bdbe-bba3b90599a0', 'f33e6456-fb48-43d3-9bd1-0c80be2847f2', 'or-IN', 'ଫଳ ବିକାଶ', 'ଫଳ ଭରୁଛି ଓ ପକ୍କା ହେଉଛି।', 'ଏହା ଆମ୍ବ ବଢିବା ଅବସ୍ଥା। ଫଳର ଆକାର ଭଲ ବଢୁଛି କି, ଫଳରେ ଦାଗ ଅଛି କି, ବା ଫଳ ଫାଟୁଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('912f554d-66f5-466a-a411-da047c662c36', '12f02f56-87f1-4361-8927-a6fad35ae75f', 'or-IN', 'ଫଳ ଧରା', 'ଛୋଟ ଫଳ ଧରୁଛି ଓ ଟିକି ରହୁଛି।', 'ଏହା ଛୋଟ ଆମ୍ବ ଧରିବା ଅବସ୍ଥା। ଛୋଟ ଫଳ ଝରିଯାଉଛି କି, ଫଳ କମ୍ ଧରିଛି କି, ବା ପତ୍ର ଏବଂ ଫୁଲରେ ପୋକ ଅଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('21e73098-e48b-470b-a8c6-4c77a845fbea', '12f02f56-87f1-4361-8927-a6fad35ae75f', 'en-IN', 'Fruit Set', 'Small fruits are setting and retaining.', 'This is the fruit setting stage. Check if small fruits are falling, if fruit setting is low, or if pests are visible on leaves and flowers.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('bea1a195-c22b-4a2f-b187-390a198204ea', 'f5f60ba5-67c0-46f4-8ca6-aa8b730d749b', 'or-IN', 'ଫୁଲ ଅବସ୍ଥା', 'ମଞ୍ଜରୀ ଓ ଫୁଲ ଦେଖାଯାଉଛି।', 'ଏହା ଆମ୍ବ ଫୁଲ ଆସିବା ଅବସ୍ଥା। ଫୁଲ ଭଲ ଆସୁଛି କି, ଫୁଲ ଝରୁଛି କି, ବା ପୋକ ଓ ଧଳା ପାଉଡର ଭଳି ରୋଗ ଦେଖାଯାଉଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('492db39b-084d-4c5d-8ca7-e10e4eeed5fb', 'f5f60ba5-67c0-46f4-8ca6-aa8b730d749b', 'en-IN', 'Flowering', 'Panicles and blooms are active.', 'This is the flowering stage of mango. Check if flowering is good, if flowers are falling, or if pests or white powder-like disease are visible.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('571a0505-d776-4817-a171-c49415925037', 'ca7898a9-cc58-4f4f-888d-0a79d35d185e', 'or-IN', 'ପତ୍ର ବୃଦ୍ଧି', NULL, 'ନମସ୍କାର। ଏହା ଆମ୍ବ ଗଛର ନୂଆ ପତ୍ର ଆସିବା ଅବସ୍ଥା। ଆପଣ ଯାହା ଗଛରେ ଦେଖୁଛନ୍ତି, ସେହି ଅନୁସାରେ ଫର୍ମ ଭରନ୍ତୁ। ଗଛର ଫଟୋ ଅପଲୋଡ୍ କରନ୍ତୁ। ଆପଣ ଚାହିଲେ ମାଇକ୍ ବଟନ୍ ଦବାଇ ନିଜ ସମସ୍ୟା କହିପାରିବେ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('416c6849-625d-48ef-b34d-aa7f8b3c469f', 'ca7898a9-cc58-4f4f-888d-0a79d35d185e', 'en-IN', 'Vegetative Flush', NULL, 'Namaskar. This is the new leaf stage of mango. Please fill the form based on what you see in the tree. Upload a photo of the tree. You can also tap the mic button and record your issue in your own words.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('cb8517c9-7b3a-45ed-ac68-2ce9f02075ef', '793b7b46-9f4a-4d37-9357-8d133996973e', 'en-IN', 'Seedling', NULL, 'Namaskar.
INSERT INTO crop_observation.crop_stage_translations VALUES ('a4a06d49-0425-456d-90aa-4d5c7389ae5d', '793b7b46-9f4a-4d37-9357-8d133996973e', 'or-IN', 'ଚାରା ଅବସ୍ଥା', NULL, 'ନମସ୍କାର।
INSERT INTO crop_observation.crop_stage_translations VALUES ('947f5ea3-123f-42cb-86dd-6dbae56b2775', '6415dce1-0386-4cf4-8184-73c68fa2c72b', 'en-IN', 'Transplanting Stage', NULL, 'This is the transplanting stage of Kala Jeera paddy. Check whether the seedlings are established properly, whether there is enough water, and whether any plants look yellow. If you want, you can record your problem in your own words.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('b62836e9-0442-4040-840f-739b482751ae', '6415dce1-0386-4cf4-8184-73c68fa2c72b', 'or-IN', 'ଜିରା ଧାନର ରୋପଣ', NULL, 'ଏହା କଳା ଜିରା ଧାନର ରୋପଣ ଅବସ୍ଥା। ଚାରା ଠିକ୍ ଭାବରେ ଲାଗିଛି କି ନାହିଁ, ପାଣି ଅଛି କି ନାହିଁ, ଏବଂ ଗଛ ହଳଦିଆ ଦେଖାଯାଉଛି କି ନାହିଁ, ଧ୍ୟାନରେ ଦେଖନ୍ତୁ। ଆପଣ ଚାହିଁଲେ ନିଜ ସମସ୍ୟା କଥାରେ ରେକର୍ଡ କରିପାରିବେ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('53d04ccd-94e8-4dd3-996f-e41ee15d6429', 'bf29cf4d-f559-4d23-8711-7f06b6dda5d7', 'en-IN', 'Panicle Initiation', NULL, 'This is the stage when panicle development begins. At this time the crop needs water and nutrients. Check whether the leaves are curling, turning yellow, or whether the plants look weak.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('5b3e8840-c586-4c7b-9b5b-dddd049969f6', 'bf29cf4d-f559-4d23-8711-7f06b6dda5d7', 'or-IN', 'ମଞ୍ଜରୀ ଆରମ୍ଭ', NULL, 'ଏହା ଧାନ କେଣ୍ଡା ବାହାରିବା ଆରମ୍ଭ ଅବସ୍ଥା। ଏହି ସମୟରେ ଗଛକୁ ପାଣି ଏବଂ ପୋଷକ ଦରକାର। ପତ୍ର ମୋଡ଼ି ହେଉଛି କି, ହଳଦିଆ ଦେଖାଯାଉଛି କି, ବା ଗଛ ଦୁର୍ବଳ ଦେଖାଯାଉଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('0ab5d7dd-5d7f-4770-8ff4-72d87f4c016d', 'f8b25387-0529-4d20-b10a-aa810605f841', 'en-IN', 'Flowering', NULL, 'This is the flowering stage. Check whether flowering is proper, whether the panicles look empty, or whether pests are visible.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('738bf4a3-c7b0-4c94-b70d-76b6a22dd39f', 'f8b25387-0529-4d20-b10a-aa810605f841', 'or-IN', 'ଫୁଲ ଅବସ୍ଥା', NULL, 'ଏହା ଫୁଲ ଆସିବା ଅବସ୍ଥା। ଏହି ସମୟରେ ଖେତରେ ପାଣି କମ୍ ହେବା ଉଚିତ୍ ନୁହେଁ। ଫୁଲ ଠିକ୍ ଆସୁଛି କି, କେଣ୍ଡା ଖାଲି ଦେଖାଯାଉଛି କି, ବା ପୋକ ଲାଗିଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('df33cc7f-455c-46f1-bd03-a7e8d215358a', 'ac85ff46-ab34-4bb3-a893-ec2403392456', 'en-IN', 'Grain Filling', NULL, 'This is the grain filling stage. Check whether the panicles are filling properly, whether the grains feel light, and whether the plants are starting to dry early. If you want, record the condition in your own words.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('ef50361c-1aba-4d18-ad0d-580fa1c1613c', 'ac85ff46-ab34-4bb3-a893-ec2403392456', 'or-IN', 'ଦାନା ପୂରଣ', NULL, 'ଏହା ଧାନ ଦାନା ଭରିବା ଅବସ୍ଥା। କେଣ୍ଡା ଭଲ ଭାବରେ ଭରୁଛି କି, ଦାନା ହାଲୁକା ଅଛି କି, ଏବଂ ଗଛ ଶୁଖିବା ଆରମ୍ଭ କରିଛି କି ନାହିଁ ଦେଖନ୍ତୁ। ଚାହିଁଲେ ନିଜ ଅବସ୍ଥା କହି ରେକର୍ଡ କରନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('7fdcbc17-01c5-4172-8c8b-085ce8839888', 'a1f8151e-b39f-4c08-8a85-391d8681b326', 'or-IN', 'ଅମଳ', NULL, 'ଏହା ଧାନ କଟା ହେବାର ପୂର୍ବ ଅବସ୍ଥା। ଧାନ ଦାନା ପାଚିଛି କି, ଗଛ ଅଧିକ ଶୁଖୁଛି କି, ଏବଂ କଟା ହେବା ପାଇଁ ଠିକ୍ ସମୟ ହୋଇଛି କି ନାହିଁ ଦେଖନ୍ତୁ। ଫଟୋ ଦେଲେ ଆମେ ଭଲ ଭାବରେ ବୁଝିପାରିବୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('58d2786c-dcaf-4695-ac29-178e13ed6f9f', 'a1f8151e-b39f-4c08-8a85-391d8681b326', 'en-IN', 'Harvesting', NULL, 'This is the stage before harvesting. Check whether the grains have matured, whether the plants are becoming too dry, and whether it is the right time for harvesting. A photo will help us understand the condition better.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('55d011a7-5375-4a33-9c85-c5c92f251a08', '99cf61c6-7f45-4827-8f48-c2a8ba06e73d', 'en-IN', 'Seedling', NULL, 'Namaskar.
INSERT INTO crop_observation.crop_stage_translations VALUES ('9372bb9f-7b49-49dd-b3d1-e764e07c8115', '99cf61c6-7f45-4827-8f48-c2a8ba06e73d', 'or-IN', 'ଚାରା ଅବସ୍ଥା', NULL, 'ନମସ୍କାର।
INSERT INTO crop_observation.crop_stage_translations VALUES ('24a61b91-f74d-4b2e-b56c-fcda54e84088', '9f571436-9d53-40ea-93f6-fd82e08b4ea6', 'en-IN', 'Transplanting Stage', NULL, 'This is the transplanting stage of Kala Jeera paddy. Check whether the seedlings are established properly, whether there is enough water, and whether any plants look yellow. If you want, you can record your problem in your own words.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('aa69b889-c924-4ff7-9947-c707045df879', '9f571436-9d53-40ea-93f6-fd82e08b4ea6', 'or-IN', 'ଜିରା ଧାନର ରୋପଣ', NULL, 'ଏହା କଳା ଜିରା ଧାନର ରୋପଣ ଅବସ୍ଥା। ଚାରା ଠିକ୍ ଭାବରେ ଲାଗିଛି କି ନାହିଁ, ପାଣି ଅଛି କି ନାହିଁ, ଏବଂ ଗଛ ହଳଦିଆ ଦେଖାଯାଉଛି କି ନାହିଁ, ଧ୍ୟାନରେ ଦେଖନ୍ତୁ। ଆପଣ ଚାହିଁଲେ ନିଜ ସମସ୍ୟା କଥାରେ ରେକର୍ଡ କରିପାରିବେ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('09b62944-9228-43ed-a063-020ec6382be2', '25dedc21-e211-4a2a-9a9b-098392bc6fa0', 'en-IN', 'Panicle Initiation', NULL, 'This is the stage when panicle development begins. At this time the crop needs water and nutrients. Check whether the leaves are curling, turning yellow, or whether the plants look weak.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('5d82058e-466e-42e4-aafa-c261f6b5c8b5', '25dedc21-e211-4a2a-9a9b-098392bc6fa0', 'or-IN', 'ମଞ୍ଜରୀ ଆରମ୍ଭ', NULL, 'ଏହା ଧାନ କେଣ୍ଡା ବାହାରିବା ଆରମ୍ଭ ଅବସ୍ଥା। ଏହି ସମୟରେ ଗଛକୁ ପାଣି ଏବଂ ପୋଷକ ଦରକାର। ପତ୍ର ମୋଡ଼ି ହେଉଛି କି, ହଳଦିଆ ଦେଖାଯାଉଛି କି, ବା ଗଛ ଦୁର୍ବଳ ଦେଖାଯାଉଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('b3674d12-a415-40f4-9aab-21bd1f4d9ac6', 'c526601e-41ab-44b4-adcf-9ae98917d234', 'en-IN', 'Flowering', NULL, 'This is the flowering stage. Check whether flowering is proper, whether the panicles look empty, or whether pests are visible.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('c2b5c201-b8f3-4f95-970a-f1f2a4ff54bb', 'c526601e-41ab-44b4-adcf-9ae98917d234', 'or-IN', 'ଫୁଲ ଅବସ୍ଥା', NULL, 'ଏହା ଫୁଲ ଆସିବା ଅବସ୍ଥା। ଏହି ସମୟରେ ଖେତରେ ପାଣି କମ୍ ହେବା ଉଚିତ୍ ନୁହେଁ। ଫୁଲ ଠିକ୍ ଆସୁଛି କି, କେଣ୍ଡା ଖାଲି ଦେଖାଯାଉଛି କି, ବା ପୋକ ଲାଗିଛି କି ନାହିଁ ଦେଖନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('799722bb-238f-4822-9d08-57604b6bdda3', 'd0161e23-892f-446d-ab55-37078634bc23', 'en-IN', 'Grain Filling', NULL, 'This is the grain filling stage. Check whether the panicles are filling properly, whether the grains feel light, and whether the plants are starting to dry early. If you want, record the condition in your own words.');
INSERT INTO crop_observation.crop_stage_translations VALUES ('d2ee7ebc-09b1-4672-910a-95d42698155d', 'd0161e23-892f-446d-ab55-37078634bc23', 'or-IN', 'ଦାନା ପୂରଣ', NULL, 'ଏହା ଧାନ ଦାନା ଭରିବା ଅବସ୍ଥା। କେଣ୍ଡା ଭଲ ଭାବରେ ଭରୁଛି କି, ଦାନା ହାଲୁକା ଅଛି କି, ଏବଂ ଗଛ ଶୁଖିବା ଆରମ୍ଭ କରିଛି କି ନାହିଁ ଦେଖନ୍ତୁ। ଚାହିଁଲେ ନିଜ ଅବସ୍ଥା କହି ରେକର୍ଡ କରନ୍ତୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('79171ceb-249e-4723-bc40-e0db72deda4c', 'f89c466b-654f-4454-a5e2-f93b499646c0', 'or-IN', 'ଅମଳ', NULL, 'ଏହା ଧାନ କଟା ହେବାର ପୂର୍ବ ଅବସ୍ଥା। ଧାନ ଦାନା ପାଚିଛି କି, ଗଛ ଅଧିକ ଶୁଖୁଛି କି, ଏବଂ କଟା ହେବା ପାଇଁ ଠିକ୍ ସମୟ ହୋଇଛି କି ନାହିଁ ଦେଖନ୍ତୁ। ଫଟୋ ଦେଲେ ଆମେ ଭଲ ଭାବରେ ବୁଝିପାରିବୁ।');
INSERT INTO crop_observation.crop_stage_translations VALUES ('e87dda72-531a-4556-b28d-bd6a5ed5961e', 'f89c466b-654f-4454-a5e2-f93b499646c0', 'en-IN', 'Harvesting', NULL, 'This is the stage before harvesting. Check whether the grains have matured, whether the plants are becoming too dry, and whether it is the right time for harvesting. A photo will help us understand the condition better.');
INSERT INTO crop_observation.crop_translations VALUES ('7708ec4e-2327-4842-aefd-b357bb2c47dd', 'b16c2113-7568-4876-9786-86080c3668fd', 'or-IN', 'ଆମ୍ବ', NULL);
INSERT INTO crop_observation.crop_translations VALUES ('5ef23281-0c79-4af4-86f5-b9f28116fbc5', 'b16c2113-7568-4876-9786-86080c3668fd', 'en-IN', 'Mango', NULL);
INSERT INTO crop_observation.crop_translations VALUES ('d3889e75-546e-47a6-ab2a-19a6e3dbbd36', 'a5ef19d2-07d0-4c13-8763-9bd7e4d900c5', 'or-IN', 'କଳାଜିରା ଧାନ', NULL);
INSERT INTO crop_observation.crop_translations VALUES ('3bdf1e21-80f7-4261-ade1-ada1b6e8c130', 'a5ef19d2-07d0-4c13-8763-9bd7e4d900c5', 'en-IN', 'Kala Jeera', NULL);
